-- Generated by scripts/build_compiled.py from src/fraudrules/rules/instant-payment/ip-003-instant-fan-out.yaml. Do not edit.
-- IP-003 Instant payments to several first-time payees within an hour
SELECT
  'IP-003' AS rule_id,
  'transactions' AS anchor_table,
  a.id AS anchor_id
FROM transactions AS a
JOIN transactions AS b
  ON b.account_id = a.account_id AND b.ts <= a.ts AND b.ts > a.ts - 3600
WHERE
  (
    a.direction = 'out'
    AND a.counterparty_new = 1
    AND a.channel IN ('rtp', 'fednow', 'p2p')
  )
  AND (
    b.direction = 'out'
    AND b.counterparty_new = 1
    AND b.channel IN ('rtp', 'fednow', 'p2p')
  )
GROUP BY
  a.id
HAVING
  (
    COUNT(DISTINCT b.counterparty_id) >= 3 AND SUM(b.amount_cents) >= 300000
  );
